head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > setVisibleRowNum]<br/>GridView 컴포넌트의 visibleRowNum 속성을 설정합니다.",
    "validation" : [
        "SubTotal Row 는 setVisibleRowNum 으로 설정한 Row 갯수에 포함되지 않습니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target/dataList 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 안내 라벨 (target 생성 전 가장 먼저 생성)
    // dept 그룹별 SubTotal(소계) Row 가 데이터 Row 사이에 삽입된 그리드.
    // setVisibleRowNum(N) 설정 시 데이터 Row N 개 기준으로 viewport 높이가 잡히고
    // SubTotal Row 는 그 갯수에 포함되지 않음을 검증.
    $c.gcm.createLabel('label="dept 컬럼 기준 SubTotal(소계) 구성. 데이터 Row 5건 + dept 그룹별 SubTotal Row 3건이 모두 표시됩니다. setVisibleRowNum(5) 설정 시 getVisibleRowNum()=5 로, SubTotal Row 3건은 갯수에 포함되지 않습니다."', '', 'label1');

    // GridView 와 바인딩할 DataList 동적 생성
    // dept(그룹 기준), amount(소계 대상 number)
    let strDlt = '';
    strDlt += '<w2:dataList ' + $c.gcm.getNameSpace() + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="name" name="name" dataType="text"></w2:column>';
    strDlt += '<w2:column id="dept" name="dept" dataType="text"></w2:column>';
    strDlt += '<w2:column id="amount" name="amount" dataType="number"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);

    // 데이터 5건 (Sales 2건 + Dev 2건 + QA 1건) -> dept 그룹 3개 -> SubTotal Row 3개 생성됨
    let jsonData = [
        { "name": "John", "dept": "Sales", "amount": 100 },
        { "name": "Jane", "dept": "Sales", "amount": 200 },
        { "name": "Mike", "dept": "Dev",   "amount": 300 },
        { "name": "Amy",  "dept": "Dev",   "amount": 400 },
        { "name": "Tom",  "dept": "QA",    "amount": 500 }
    ];
    dlt_bind.setJSON(jsonData, false);

    // Property 설정은 createCList 공통 함수 사용
    let properties = {
        dataList: "data:dlt_bind",
    };
    let cList = $c.gcm.createCList(properties);

    let grp_comp = $c.gcm.getTestGroup();
    let strNameSpace = $c.gcm.getNameSpace();
    let strTarget = '';

    // Header(이름/부서/금액) + gBody(데이터) + SubTotal(부서별 소계)
    // - SubTotal : targetColumnID="dept" -> dept 가 바뀔 때마다 소계 Row 삽입, amount 에 sum('amount') expression
    // - 마지막 컬럼 width="*" 로 가로 스크롤 방지
    // - 디자인 높이를 작게(약 2~3행) 설정 -> setVisibleRowNum 설정 시 높이 변화 관찰 용이
    strTarget += '<w2:gridView ' + strNameSpace + ' ' + cList + ' id="" style="width:520px;height:150px;">';
    strTarget += '<w2:caption style="" id="caption1" value="setVisibleRowNum SubTotal 테스트 그리드"></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="hrow1">';
    strTarget += '<w2:column width="160" style="" inputType="text" id="hcol1" value="이름"></w2:column>';
    strTarget += '<w2:column width="160" style="" inputType="text" id="hcol2" value="부서"></w2:column>';
    strTarget += '<w2:column width="*" style="" inputType="text" id="hcol3" value="금액"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="brow1">';
    strTarget += '<w2:column width="160" style="" inputType="text" id="name" dataList="name"></w2:column>';
    strTarget += '<w2:column width="160" style="" inputType="text" id="dept" dataList="dept"></w2:column>';
    strTarget += '<w2:column width="*" style="" inputType="text" dataType="number" displayFormat="#,###" id="amount" dataList="amount"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    // SubTotal : dept 기준 소계 Row (dept 값이 바뀌는 지점마다 삽입)
    strTarget += '<w2:subTotal style="" id="subTotal1" targetColumnID="dept">';
    strTarget += '<w2:row style="" id="srow1">';
    strTarget += '<w2:column width="160" style="" inputType="text" id="scol1" value="소계(SubTotal)"></w2:column>';
    strTarget += '<w2:column width="160" style="" inputType="text" id="scol2" value=""></w2:column>';
    strTarget += '<w2:column width="*" style="" inputType="expression" dataType="number" displayFormat="#,###" id="scol3" expression="sum(\'amount\')"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:subTotal>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate('target1', 'gridView', strTarget, grp_comp);

    // // 초기 로드 시 setVisibleRowNum(5) 적용 → 작은 디자인 높이(150px)에서 grow 하여 데이터 5행 + SubTotal 3행이 모두 표시됨
    // setTimeout(function () {
    //     target1.setVisibleRowNum(5);
    // }, 100);
}



// setVisibleRowNum(rowNum) — 설정 후 데이터 Row 수(getVisibleRowNum)는 SubTotal 미포함
scwin.btn_setVisibleRowNum_onclick = function (e) {
    let rowNum = Number(par_rowNum.getValue());

    // 먼저 작은 높이로 만든 뒤 setVisibleRowNum 호출 → grow 동작으로 데이터 rowNum 행 + 해당 SubTotal Row 가 모두 보이도록 높이 재조정
    // (이미 큰 높이에서 setVisibleRowNum 을 호출하면 데이터 행수 기준으로 shrink 되어 일부 행/소계가 가려짐)
    // target1.setGridHeight(150);
    setTimeout(function () {
        target1.setVisibleRowNum(rowNum);
        // getVisibleRowNum() 은 redraw 정착 후 읽어야 정확. SubTotal Row 는 rowNum 갯수에 미포함
        setTimeout(function () {
            wf_body_bottom.getObj("scwin").setReturnValue("setVisibleRowNum(" + rowNum + ") 설정 후 getVisibleRowNum() : " + target1.getVisibleRowNum());
        }, 700);
    }, 100);
}
